import{_ as t}from"./chunks/users.Q57XcA06.js";import{_ as a,o as r,c as s,a2 as n}from"./chunks/framework.DSc8fo6x.js";const p=JSON.parse('{"title":"Users","description":"","frontmatter":{},"headers":[],"relativePath":"en/istifadeciler.md","filePath":"en/istifadeciler.md"}'),o={name:"en/istifadeciler.md"};function i(l,e,d,h,c,g){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h1><p><strong>Admin</strong> only.</p><p><img src="'+t+'" alt="Users"></p><h2 id="new-user" tabindex="-1">New user <a class="header-anchor" href="#new-user" aria-label="Permalink to &quot;New user&quot;">​</a></h2><p><strong>New user</strong> → name, role, password.</p><table tabindex="0"><thead><tr><th>Role</th><th>What they can do</th><th>Password</th></tr></thead><tbody><tr><td><strong>Cashier</strong></td><td>Sell, view stock and their own sales</td><td>at least 4 characters (e.g. 4 digits)</td></tr><tr><td><strong>Admin</strong></td><td>Everything: products, prices, receiving, voids, reports, users, settings</td><td>at least 8 characters, letters and digits</td></tr></tbody></table><h2 id="password" tabindex="-1">Password <a class="header-anchor" href="#password" aria-label="Permalink to &quot;Password&quot;">​</a></h2><ul><li>If someone forgets their password, the admin sets a new one with the <strong>Password</strong> button.</li><li>Everyone can change their own password: click your name at the bottom left → <strong>Change password</strong>.</li></ul><h2 id="lock" tabindex="-1">Lock <a class="header-anchor" href="#lock" aria-label="Permalink to &quot;Lock&quot;">​</a></h2><p>If someone enters a wrong password <strong>10 times</strong>, they must wait 1 minute (after the 3rd mistake they see how many attempts are left). The admin can unlock them right away with <strong>Unlock</strong>. The number and the time can be changed in <a href="./ayarlar.html">Settings</a>.</p><h2 id="an-employee-leaves" tabindex="-1">An employee leaves <a class="header-anchor" href="#an-employee-leaves" aria-label="Permalink to &quot;An employee leaves&quot;">​</a></h2><p><strong>Deactivate</strong> — the user is not deleted and their past sales stay, but they cannot log in.</p><h2 id="mesq" tabindex="-1">Training mode: teaching a new cashier <a class="header-anchor" href="#mesq" aria-label="Permalink to &quot;Training mode: teaching a new cashier {#mesq}&quot;">​</a></h2><p><strong>Help → Training mode (cashier practice)</strong> → duration (15 min–2 hours) → <strong>Start training</strong>.</p><ul><li>The sale screen works fully: scanning, cash/card, change. But sales are <strong>not recorded</strong> and stock does not change.</li><li>An orange <strong>&quot;TRAINING MODE&quot;</strong> bar with the remaining time shows on every screen.</li><li><strong>Real sales are not possible</strong> meanwhile — train when there are no customers.</li><li>The mode turns itself off when the time is up; to finish earlier — <strong>End training</strong>.</li><li>Only an <strong>admin</strong> can turn it on (not a cashier). Turning it on and off is recorded in the log and the daily Telegram report.</li></ul>',15)])])}const w=a(o,[["render",i]]);export{p as __pageData,w as default};
